"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Unburied', 'author': 'Signature original', 'genre': 'Ghost Stories', 'chapters': [{'n': 1, 'title': 'Move-In', 'text': "The first night, Ben Marsh found a locked nursery. It wasn't in any box. It was waiting — on the mantel, in the nursery, at the foot of the bed, depending on which telling you believe. This telling says: the mantel.\n\nthe medium Madame Zara helped carry boxes and didn't stay for dinner. 'Call me,' the medium Madame Zara said, 'if the walls start talking.' It was a joke. Ben Marsh laughed. The house didn't.\n\nBen Marsh told themselves it was the previous tenant's. Left behind. Nothing more. But at 3 a.m., a locked nursery did what a locked nursery does, and Ben Marsh sat up in the dark with their heart hammering the truth: this was no leftover."}, {'n': 2, 'title': 'Escalation', 'text': "Day three: a locked nursery moved on its own. Day four: the whispers started in the walls, spelling a name Ben Marsh almost recognized. Day five: the medium Madame Zara came for dinner and went white at the cold spot on the stairs.\n\n'the drowned choir,' the medium Madame Zara whispered, though Ben Marsh hadn't said the name yet. Everyone in the county knew the story of the marsh village. Everyone pretended they didn't.\n\nBen Marsh researched. The archives gave up their dead reluctantly: a death in the marsh village, then another, then the silence that means everyone agreed not to speak. a locked nursery appeared in every account, patient as a spider."}, {'n': 3, 'title': 'The Pattern', 'text': "The nursery door, locked for decades, opened for Ben Marsh like it had been waiting. Inside: dust, a small bed, and a locked nursery's twin — the other half of whatever had been broken that terrible night.\n\nThe whispers became a voice. It knew Ben Marsh's name. It offered a deal: leave the marsh village, leave a locked nursery, and walk away clean. Ben Marsh considered it for exactly as long as it took to be afraid — then refused.\n\n'courage is a light,' Ben Marsh said to the dark, and the dark laughed. But it was a nervous laugh. Even the drowned choir could tell: this one wasn't going to run."}, {'n': 4, 'title': 'The Night', 'text': "What followed wasn't a fight; it was a siege of the soul. the drowned choir wore the faces of everyone Ben Marsh loved, starting with the medium Madame Zara, begging to be let in, to be believed, to be obeyed. Ben Marsh held the line with the oldest weapon: names, spoken true.\n\nBen Marsh understood then what had to be done: not destroy a locked nursery, but complete it. Join the halves. Speak the name. Give the drowned choir what it had wanted all along — to be seen, to be mourned, to be released.\n\nIt came on the anniversary, as Ben Marsh knew it would. The fog pressed against the windows of the marsh village like a face. a locked nursery activated — played, filled, showed, rang, drew, unlocked — and the drowned choir stepped out of the walls."}, {'n': 5, 'title': 'Aftermath', 'text': "a locked nursery, mended, sits on the mantel. It doesn't play, or fill, or show. It's just an object now — which is to say, it's just a story. Ben Marsh keeps it to remember: courage is a light.\n\nThe archives got a new entry, in Ben Marsh's handwriting: what happened, what worked, what it cost. Let the next tenant know. Let no one ever pretend again.\n\nDawn in the marsh village was just dawn — fog burning off, birds being birds. Ben Marsh slept fourteen hours and woke to the medium Madame Zara making pancakes like nothing had happened, which was exactly the right thing."}, {'n': 6, 'title': 'Epilogue: The Light Kept', 'text': "Years later, Ben Marsh still walks the marsh village at night, checking the rooms the way you check on sleeping children. The nursery is a study now. The cold spot is just a draft. Mostly.\n\ncourage is a light — Ben Marsh wrote it on the first page of the archive, and on the last. Whoever comes next will read it. Whoever comes next will know.\n\nthe medium Madame Zara visits every anniversary with pancakes and bad jokes. They don't talk about that night. They don't need to. It's in the walls — but the walls, now, are just walls."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

